    },
    "local/canary",
    {
      "id": "claude-code-web-users-support",
      "version": "60823.1",
      "answers": {
        "store": "missingbulb/Shepherd"
      },
      "config": {
        "repo": "missingbulb/Shepherd"
      }
    },
    {
      "id": "claudinite-canary-repo",
      "version": "60822.1"
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60823.1"
    },
    {
      "id": "claudinite-dashboard",
      "version": "60823.1",
      "answers": {
        "mode": "repo — this deployment is Canary's own page; it covers no other repo"
      },
      "config": {
        "mode": "repo"
      }
    }
  ],
